import styled from '@emotion/styled';

import type {
  BigNumberAlignment,
  BigNumberOrientation,
  BigNumberSpacing,
} from 'components/BigNumber/types';

export const StyledBigNumberCenteredWrapper = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
});

export const StyledBigNumberCenteredSecondaryInfo = styled.div({
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  paddingTop: '12px',
});

export const StyledBigNumberColumnDivider = styled.div({
  width: '1px',
  minHeight: '100%',
  alignSelf: 'stretch',
  flexShrink: 0,
  margin: '0 8px',
  background: '#14141414',
});

interface StyledBigNumberItemContainerProps {
  $orientation?: BigNumberOrientation;
  $alignment?: BigNumberAlignment;
}

export const StyledBigNumberItemContainer = styled.div<StyledBigNumberItemContainerProps>(
  ({ $orientation = 'vertical', $alignment = 'left' }) => ({
    display: 'flex',
    flexDirection: 'row',
    gap: '8px',
    ...($orientation === 'horizontal' && {
      display: 'grid',
      gap: '80px',
    }),
    ...($orientation === 'vertical' &&
      $alignment === 'left' && {
        justifyContent: 'space-between',
      }),
    ...($orientation === 'vertical' &&
      $alignment === 'center' && {
        width: '100%',
        gap: 0,
      }),
  }),
);

interface StyledBigNumberItemContentProps {
  $spacing?: BigNumberSpacing;
  $alignment?: BigNumberAlignment;
  $orientation?: BigNumberOrientation;
}

export const StyledBigNumberItemContent = styled.div<StyledBigNumberItemContentProps>(
  ({ $spacing, $alignment, $orientation }) => ({
    display: 'flex',
    flexDirection: 'column',
    gap: '4px',
    ...($spacing === 'loose' && { gap: '16px' }),
    ...($spacing === 'cozy' && { gap: '4px' }),
    ...($alignment === 'center' && {
      alignItems: 'center',
      textAlign: 'center',
    }),
    ...($orientation === 'center' && { alignItems: 'flex-start' }),
    ...($alignment === 'center' &&
      $orientation === 'vertical' && {
        flex: 1,
        minWidth: 0,
        justifyContent: 'center',
      }),
  }),
);

interface StyledBigNumberMainContentProps {
  $alignment?: BigNumberAlignment;
}

export const StyledBigNumberMainContent = styled.div<StyledBigNumberMainContentProps>(
  ({ $alignment = 'left' }) => ({
    display: 'flex',
    alignItems: 'center',
    gap: '4px',
    ...($alignment === 'center' && { justifyContent: 'center' }),
  }),
);

interface StyledBigNumberComparisonContainerProps {
  $preserveSpace?: boolean;
  $alignment?: BigNumberAlignment;
}

export const StyledBigNumberComparisonContainer = styled.div<StyledBigNumberComparisonContainerProps>(
  ({ $preserveSpace = false, $alignment = 'left' }) => ({
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
    alignItems: 'start',
    gap: '4px',
    ...($preserveSpace && { minWidth: '20px' }),
    ...($alignment === 'center' && { alignItems: 'center' }),
  }),
);

export const StyledBigNumberSecondaryInfoContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
});

interface StyledBigNumberSecondaryInfoValueProps {
  $hasValue?: boolean;
}

export const StyledBigNumberSecondaryInfoValue = styled.div<StyledBigNumberSecondaryInfoValueProps>(
  ({ $hasValue }) => ({
    display: 'flex',
    gap: $hasValue ? '4px' : '0px',
    alignItems: 'center',
  }),
);
